class Animal:
    species = 'Unknown'  # class variable

    def __init__(self, name: str, age: int):
        self.name = name
        self.age = age

    def speak(self) -> str:
        return f'{self.name} makes a sound'

    def __repr__(self): return f'Animal({self.name!r})'

    @classmethod
    def from_dict(cls, d): return cls(d['name'], d['age'])

    @staticmethod
    def is_valid_age(age): return 0 <= age <= 150


class Dog(Animal):
    def __init__(self, name, age, breed):
        super().__init__(name, age)
        self.breed = breed

    def speak(self): return f'{self.name} says Woof!'

    @property
    def info(self): return f'{self.name} ({self.breed})'


d = Dog('Rex', 3, 'Lab')
print(d.speak())
print(isinstance(d, Animal))  # True
print(d.info)
